using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed
            // EF Core 9 writes "$type" instead of "Discriminator".
            // Existing 500K documents use "Discriminator", and raw SQL queries
            // (SELECT … WHERE c.Discriminator = 'Product') depend on it.
            // Restore the old name so reads, writes, and SQL all stay compatible.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — id format changed
            // EF Core 8 synthesised id as "Product|{Key}"; EF Core 9 uses just "{Key}".
            // Existing documents have id = "Product|123". We keep the legacy format by
            // mapping an explicit string key that includes the type prefix.
            entity.HasKey(p => p.CosmosId);
            entity.Property(p => p.CosmosId)
                  .ToJsonProperty("id")
                  .HasValueGeneratorFactory<LegacyCosmosIdGeneratorFactory>();

            // BREAKING CHANGE 3 — HasIndex not supported
            // EF Core 9 throws for HasIndex on Cosmos. Removed the HasIndex(p => p.Sku)
            // call. Cosmos indexing is managed via the Azure portal index policy, not EF.
        });
    }
}

/// <summary>Generates id values in the EF Core 8 "Product|{n}" format.</summary>
class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
        => $"Product|{entry.Property(nameof(Product.Id)).CurrentValue}";
}

class LegacyCosmosIdGeneratorFactory : ValueGeneratorFactory
{
    public override ValueGenerator Create(
        Microsoft.EntityFrameworkCore.Metadata.IProperty property,
        Microsoft.EntityFrameworkCore.Metadata.ITypeBase typeBase)
        => new LegacyCosmosIdGenerator();
}

class Product
{
    public string CosmosId { get; set; }   // maps to JSON "id", e.g. "Product|42"
    public int Id { get; set; }
    public string Sku { get; set; }
}

